create or replace function public.get_developer_guard_settings_rc1(p_guard_id uuid) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare g public.guards; p public.profiles; u_email text; begin if not exists(select 1 from public.profiles where id=auth.uid() and role='platform_admin') then raise exception 'PLATFORM_ADMIN_REQUIRED'; end if; select * into g from public.guards where id=p_guard_id; if g.id is null then raise exception 'GUARD_PROFILE_NOT_FOUND'; end if; select * into p from public.profiles where id=g.user_id; select email into u_email from auth.users where id=g.user_id; return jsonb_build_object('id',g.id,'user_id',g.user_id,'agency_id',g.agency_id,'name',coalesce(p.full_name,u_email,'Guard'),'email',coalesce(u_email,''),'avatar_url',g.avatar_url,'phone',coalesce(g.phone,p.phone),'badge_number',g.badge_number,'availability',g.availability,'emergency_contact_name',g.emergency_contact_name,'emergency_contact_phone',g.emergency_contact_phone,'preferred_shift',g.preferred_shift,'max_travel_miles',g.max_travel_miles,'notification_preferences',g.notification_preferences); end $$;
create or replace function public.update_developer_guard_settings_rc1(p_guard_id uuid,p_avatar_url text,p_phone text,p_emergency_contact_name text,p_emergency_contact_phone text,p_preferred_shift text,p_max_travel_miles integer,p_notification_preferences jsonb) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ begin if not exists(select 1 from public.profiles where id=auth.uid() and role='platform_admin') then raise exception 'PLATFORM_ADMIN_REQUIRED'; end if; if p_preferred_shift not in ('any','day','evening','overnight') then raise exception 'INVALID_SHIFT'; end if; if p_max_travel_miles not between 1 and 250 then raise exception 'INVALID_TRAVEL_RADIUS'; end if; update public.guards set avatar_url=nullif(trim(p_avatar_url),''),phone=nullif(trim(p_phone),''),emergency_contact_name=nullif(trim(p_emergency_contact_name),''),emergency_contact_phone=nullif(trim(p_emergency_contact_phone),''),preferred_shift=p_preferred_shift,max_travel_miles=p_max_travel_miles,notification_preferences=coalesce(p_notification_preferences,'{}'::jsonb),updated_at=now() where id=p_guard_id; if not found then raise exception 'GUARD_PROFILE_NOT_FOUND'; end if; return public.get_developer_guard_settings_rc1(p_guard_id); end $$;
grant execute on function public.get_developer_guard_settings_rc1(uuid) to authenticated;grant execute on function public.update_developer_guard_settings_rc1(uuid,text,text,text,text,text,integer,jsonb) to authenticated;
